<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="csrf-token" content="{{ csrf_token() }}"><title>CBT Management · Tagore ERP</title><link rel="stylesheet" href="{{ asset('tagore-erp.css') }}">
<style>body{font:15px system-ui;background:#f3f6fb;color:#172033;margin:0}.shell{max-width:1100px;margin:auto;padding:22px 16px}.panel{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px;margin:12px 0}input,select,textarea{display:block;width:100%;box-sizing:border-box;padding:10px;margin:6px 0 12px;border:1px solid #cbd5e1;border-radius:7px}button{background:#173b69;color:#fff;border:0;border-radius:7px;padding:10px 14px;cursor:pointer}.muted{color:#64748b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.item{padding:10px;border-bottom:1px solid #e2e8f0}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head>
<body><main class="shell"><header class="panel"><h1>JEE / NEET CBT Management</h1><a href="{{ route('tagore.dashboard') }}">Back to dashboard</a></header>
<div id="notice" class="panel muted">Create a question bank, add or import questions, then assemble and publish an exam. Publishing locks the exam questions.</div>
<div class="grid"><section class="panel"><h2>Question banks</h2><form id="bank"><label>Institution ID<input name="institution_id" type="number" min="1" required></label><label>Academic year ID (optional)<input name="academic_year_id" type="number" min="1"></label><label>Bank name<input name="name" required maxlength="160"></label><label>Exam track<select name="exam_track"><option>JEE_MAIN</option><option>JEE_ADVANCED</option><option>NEET</option></select></label><button>Create bank</button></form>
<h3>Existing banks</h3>@foreach($banks as $bank)<div class="item"><strong>{{ $bank->name }}</strong> · {{ $bank->exam_track }} · ID {{ $bank->id }}</div>@endforeach</section>
<section class="panel"><h2>Create exam</h2><form id="exam"><label>Institution ID<input name="institution_id" type="number" min="1" required></label><label>Academic year ID<input name="academic_year_id" type="number" min="1"></label><label>Exam title<input name="title" required maxlength="180"></label><label>Track<select name="exam_track"><option>JEE_MAIN</option><option>JEE_ADVANCED</option><option>NEET</option></select></label><label>Duration (minutes)<input name="duration_minutes" type="number" min="1" max="600" value="180" required></label><label>Starts at<input name="starts_at" type="datetime-local"></label><label>Ends at<input name="ends_at" type="datetime-local"></label><button>Create draft exam</button></form>
<h3>Exams</h3>@foreach($exams as $exam)<div class="item"><strong>{{ $exam->title }}</strong> · {{ $exam->exam_track }} · {{ $exam->status }} · ID {{ $exam->id }}
@if($exam->status === 'draft')<form class="schedule-form" data-id="{{ $exam->id }}"><label>Start<input name="starts_at" type="datetime-local" value="{{ $exam->starts_at ? \Illuminate\Support\Carbon::parse($exam->starts_at)->format('Y-m-d\\TH:i') : '' }}"></label><label>End<input name="ends_at" type="datetime-local" value="{{ $exam->ends_at ? \Illuminate\Support\Carbon::parse($exam->ends_at)->format('Y-m-d\\TH:i') : '' }}"></label><button>Save schedule</button></form>@endif
<button type="button" class="analytics" data-id="{{ $exam->id }}">View performance</button></div>@endforeach
<div id="analyticsResult" class="panel" aria-live="polite">Select an exam to view its results and subject-wise performance.</div></section></div>
<section class="panel"><h2>Question entry / bulk import</h2><p class="muted">Bulk import accepts a JSON array of question objects. Every row is validated; a failed row rolls back the whole batch.</p><label>Bank ID<input id="bankId" type="number"></label><label>Questions JSON<textarea id="questions" rows="8" placeholder='[{"subject_code":"physics","difficulty":"medium","question_type":"single_choice","stem":"...","options":{"A":"...","B":"..."},"answer_key":"A","default_marks":4,"default_negative_marks":1}]'></textarea></label><button id="import">Import questions</button>
<hr><h2>Assemble and publish</h2><label>Draft exam ID<input id="examId" type="number"></label><label>Question mapping JSON<textarea id="mapping" rows="5" placeholder='[{"question_id":1,"section_code":"physics","marks":4,"negative_marks":1}]'></textarea></label><button id="attach">Attach questions</button> <button id="publish">Publish exam</button></section>
</main><script>
(()=>{const csrf=document.querySelector('meta[name="csrf-token"]').content,$=id=>document.getElementById(id),notice=(m)=>{$('notice').textContent=m;};
const api=async(url,method='POST',body={})=>{const r=await fetch(url,{method,credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(body)});const d=await r.json().catch(()=>({message:'Unexpected response'}));if(!r.ok)throw new Error(d.message||JSON.stringify(d.errors||{}));return d;};
const form=f=>Object.fromEntries(new FormData(f).entries());
$('bank').onsubmit=async e=>{e.preventDefault();try{const d=await api('/tagore/cbt/banks','POST',form(e.target));notice('Question bank created: '+d.bank_id+'. Refresh to see it.');}catch(x){notice(x.message);}};
$('exam').onsubmit=async e=>{e.preventDefault();try{const d=await api('/tagore/cbt/exams','POST',form(e.target));notice('Draft exam created: '+d.exam_id+'.');}catch(x){notice(x.message);}};
$('import').onclick=async()=>{try{const d=await api('/tagore/cbt/banks/'+$('bankId').value+'/questions/import','POST',{questions:JSON.parse($('questions').value)});notice('Imported '+d.imported+' questions.');}catch(x){notice(x.message);}};
$('attach').onclick=async()=>{try{const d=await api('/tagore/cbt/exams/'+$('examId').value+'/questions','POST',{questions:JSON.parse($('mapping').value)});notice('Attached '+d.attached+' questions.');}catch(x){notice(x.message);}};
document.querySelectorAll('.schedule-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const d=await api('/tagore/cbt/exams/'+f.dataset.id+'/schedule','PATCH',form(f));notice('Exam schedule saved.');}catch(x){notice(x.message);}});
document.querySelectorAll('.analytics').forEach(b=>b.onclick=async()=>{try{const d=await api('/tagore/cbt/exams/'+b.dataset.id+'/analytics','GET');const box=$('analyticsResult');box.replaceChildren();const h=document.createElement('h3');h.textContent='Exam performance';box.append(h);const summary=document.createElement('p');summary.textContent='Attempts: '+d.attempt_count+' · Average score: '+d.average_score+' · Average accuracy: '+d.average_accuracy+'%';box.append(summary);const sh=document.createElement('h4');sh.textContent='Subject breakdown';box.append(sh);d.subject_breakdown.forEach(x=>{const p=document.createElement('p');p.textContent=x.subject_code+': '+x.correct_count+'/'+x.response_count+' correct · average marks '+x.average_marks;box.append(p);});const lh=document.createElement('h4');lh.textContent='Leaderboard';box.append(lh);d.leaderboard.forEach(x=>{const p=document.createElement('p');p.textContent='#'+x.rank+' '+(x.student_name||('Student '+x.student_id))+' · '+x.score+'/'+x.max_score+' · '+x.percentile+' percentile';box.append(p);});}catch(x){notice(x.message);}});
$('publish').onclick=async()=>{if(!confirm('Publish this exam? Published exams cannot be edited.'))return;try{const d=await api('/tagore/cbt/exams/'+$('examId').value+'/publish','PATCH',{});notice('Published successfully with '+d.question_count+' questions.');}catch(x){notice(x.message);}};
})();
</script></body></html>